SELECT (DATE_TRUNC('DAY', "GRANTED_AT")) AS "TIME_BUCKET", SUM(CASE WHEN ROLE_NAME IN ('ACCOUNTADMIN', 'SECURITYADMIN', 'ORGADMIN') AND REVOKED_AT IS NULL THEN 1 ELSE 0 END) AS "SEC_PRIVILEGED_GRANTS" FROM (SELECT g."ROLE" AS ROLE_NAME, g."GRANTED_TO" AS GRANTED_TO, g."GRANTEE_NAME" AS GRANTEE_NAME, g."GRANTED_BY" AS GRANTED_BY, (TRY_TO_TIMESTAMP_NTZ(g."CREATED_ON")) AS GRANTED_AT, (TRY_TO_TIMESTAMP_NTZ(g."DELETED_ON")) AS REVOKED_AT, COALESCE(u."DISABLED", FALSE) AS GRANTEE_DISABLED, u."TYPE" AS GRANTEE_TYPE, (TRY_TO_TIMESTAMP_NTZ(u."LAST_SUCCESS_LOGIN")) AS GRANTEE_LAST_LOGIN_AT, (NULL) AS ACCOUNT_NAME /* The account these rows came from (see the ACCOUNT_OF shim). */ FROM grants_to_users AS g LEFT JOIN users AS u ON u."NAME" = g."GRANTEE_NAME" AND COALESCE((NULL), '') = COALESCE((NULL), '')) AS base GROUP BY (DATE_TRUNC('DAY', "GRANTED_AT")) ORDER BY "SEC_PRIVILEGED_GRANTS" DESC NULLS LAST, "TIME_BUCKET" LIMIT 100
